import { NextResponse } from 'next/server';
import { ServerStore } from '@/lib/server-store';
import { createSuccessResponse, createErrorResponse } from '@/lib/security';
import { verifyRazorpayPaymentSignature } from '@/lib/payment-security';
import { getOrderAuthContext } from '@/lib/server-auth';

/**
 * Server-Side Razorpay Payment Signature Verification
 * 
 * Verifies that the payment signature returned by the Razorpay checkout
 * was cryptographically generated by Razorpay using RAZORPAY_KEY_SECRET.
 * A client cannot forge this signature or mark an order paid without valid gateway proof.
 */
export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { orderNumber, razorpay_order_id, razorpay_payment_id, razorpay_signature } = body;

    if (!orderNumber || !razorpay_order_id || !razorpay_payment_id || !razorpay_signature) {
      return NextResponse.json(
        createErrorResponse(
          'MISSING_FIELDS',
          'orderNumber, razorpay_order_id, razorpay_payment_id, and razorpay_signature are strictly required.'
        ),
        { status: 400 }
      );
    }

    const cleanNum = String(orderNumber).trim().toUpperCase();
    const order = ServerStore.getOrderById(cleanNum);
    if (!order) {
      return NextResponse.json(
        createErrorResponse('ORDER_NOT_FOUND', `Order #${cleanNum} not found.`),
        { status: 404 }
      );
    }

    // Verify caller authorization
    const authContext = getOrderAuthContext(request, order);
    if (!authContext.isAdmin && !authContext.isCustomerOwner && !authContext.isOrderTokenHolder) {
      return NextResponse.json(
        createErrorResponse('FORBIDDEN', 'You are not authorized to verify payment for this order.'),
        { status: 403 }
      );
    }

    // Idempotency: Return success if this transaction ID was already captured
    if (ServerStore.isWebhookProcessed(razorpay_payment_id) || order.paymentStatus === 'PAID') {
      return NextResponse.json(
        createSuccessResponse({
          verified: true,
          orderNumber: cleanNum,
          paymentStatus: 'PAID',
          transactionId: razorpay_payment_id,
          message: 'Payment was already verified and captured.',
        })
      );
    }

    // Cryptographic signature verification
    const isValid = verifyRazorpayPaymentSignature(
      razorpay_order_id,
      razorpay_payment_id,
      razorpay_signature
    );

    if (!isValid) {
      ServerStore.recordPaymentFailure(cleanNum, 'Cryptographic payment signature verification failed.', {
        gateway: 'RAZORPAY',
        transactionId: razorpay_payment_id,
      });

      return NextResponse.json(
        createErrorResponse(
          'INVALID_SIGNATURE',
          'Forged or invalid payment signature. Payment verification rejected.'
        ),
        { status: 400 }
      );
    }

    // Verify and capture payment in server store
    const captureResult = ServerStore.verifyAndCapturePayment(cleanNum, {
      gateway: 'RAZORPAY',
      transactionId: razorpay_payment_id,
      gatewayOrderId: razorpay_order_id,
      amount: order.totalAmount,
      currency: 'INR',
    });

    if (!captureResult.success) {
      return NextResponse.json(
        createErrorResponse(captureResult.error || 'CAPTURE_FAILED', captureResult.message),
        { status: 400 }
      );
    }

    // Record transaction ID in processed events
    ServerStore.recordProcessedWebhook(razorpay_payment_id);

    console.log(
      `[RAZORPAY VERIFIED] Order #${cleanNum} payment successfully captured (Payment ID: ${razorpay_payment_id})`
    );

    return NextResponse.json(
      createSuccessResponse({
        verified: true,
        orderNumber: cleanNum,
        paymentStatus: 'PAID',
        transactionId: razorpay_payment_id,
        orderStatus: captureResult.order?.status || 'ACCEPTED',
      })
    );
  } catch (err: any) {
    return NextResponse.json(createErrorResponse('VERIFY_ERROR', err.message), { status: 500 });
  }
}
